/// Returns true if there exists an index i such that
/// a[i] + 1 == a[i + 1].
/// If the slice has fewer than two elements, returns false.
fn contains_consecutive_numbers(a: &Vec<i32>) -> bool {
    // Iterate over all adjacent pairs
    a.windows(2).any(|pair| pair[1] == pair[0] + 1)
}

