    #[test]
    fn empty_and_single() {
        let v: Vec<i32> = vec![];
        assert!(!contains_consecutive_numbers(&v));
        let v = vec![42];
        assert!(!contains_consecutive_numbers(&v));
    }

    #[test]
    fn no_consecutive() {
        let v = vec![1, 3, 2, 5, 5];
        assert!(!contains_consecutive_numbers(&v));
    }

    #[test]
    fn has_consecutive() {
        let v = vec![4, 5];
        assert!(contains_consecutive_numbers(&v));

        let v = vec![0, 1, 1, 2, 3];
        assert!(contains_consecutive_numbers(&v)); // 0->1 and 1->2
    }

    #[test]
